function writeOutputs(outputDir, opts, detector, trajectories, photonEvents, ...
        photophysics, localizationTable, trackTable, diffusion, ...
        densityDiagnostics, experimentalBnp, frames)
    import membrane_tracking.focused_ism.*

    ensureDir(outputDir);

    writetable(photonEvents, fullfile(outputDir, 'photon_events.csv'));
    writetable(localizationTable, fullfile(outputDir, ...
        'localizations_fisher_crb.csv'));
    writetable(trackTable, fullfile(outputDir, 'particle_tracks.csv'));
    writetable(diffusion.msdTable, fullfile(outputDir, ...
        'diffusion_msd_summary.csv'));

    summary = table(opts.diffusionUm2PerS, diffusion.DLag1CorrectedUm2PerS, ...
        diffusion.DMsdCorrectedUm2PerS, diffusion.DMsdRawUm2PerS, ...
        diffusion.DFisherMLEUm2PerS, diffusion.DFisherCRBUm2PerS, ...
        diffusion.diffusionFisherInformation, ...
        diffusion.nIndependentStepsForFisher, ...
        diffusion.nTracksTotal, diffusion.nTracksUsed, ...
        opts.actualMoleculeConcentrationPerUm2, ...
        diffusion.fractionAmbiguousAssociations, ...
        diffusion.fractionUncertainEmitterCounts, ...
        diffusion.fractionRejectedForDiffusion, ...
        diffusion.meanAssociationProbability, ...
        diffusion.meanEmitterCountPosteriorProbability, ...
        diffusion.meanHardGateAcceptanceProbability, ...
        diffusion.fractionNonidentifiablePositions, ...
        diffusion.nTrackingRefinementIterations, ...
        1000 * diffusion.meanLocalizationSigmaUm, ...
        1000 * diffusion.medianLocalizationSigmaUm, ...
        experimentalBnp.posteriorMeanD, ...
        experimentalBnp.credibleIntervalD(1), ...
        experimentalBnp.credibleIntervalD(2), ...
        experimentalBnp.effectiveSampleSizeD, ...
        experimentalBnp.splitRhatD, ...
        experimentalBnp.posteriorMeanEmittersInFocus, ...
        experimentalBnp.posteriorMapActiveEmitterCount, ...
        experimentalBnp.activeEmitterCountDecisionProbability, ...
        experimentalBnp.activeEmitterCountEntropyBits, ...
        experimentalBnp.medianFrameCountDecisionProbability, ...
        experimentalBnp.adjacentCountSeparationSigma, ...
        experimentalBnp.countDiagnosticsPassed, ...
        experimentalBnp.passedApplicabilityChecks, ...
        experimentalBnp.isValidatedForUse, ...
        'VariableNames', {'trueDiffusionUm2PerS', ...
        'lag1FisherCorrectedDiffusionUm2PerS', ...
        'msdFisherCorrectedDiffusionUm2PerS', 'rawMsdDiffusionUm2PerS', ...
        'stepLikelihoodDiffusionUm2PerS', ...
        'stepLikelihoodDiffusionCrbUm2PerS', ...
        'stepLikelihoodDiffusionFisherInformation', ...
        'nIndependentStepsForFisher', 'nTracksTotal', ...
        'nTracksUsed', 'moleculeConcentrationPerUm2', ...
        'fractionAmbiguousAssociations', ...
        'fractionUncertainEmitterCounts', ...
        'fractionRejectedForDiffusion', ...
        'meanAssociationProbability', ...
        'meanEmitterCountPosteriorProbability', ...
        'meanHardGateAcceptanceProbability', ...
        'fractionNonidentifiablePositions', ...
        'nTrackingRefinementIterations', ...
        'meanLocalizationSigmaNm', ...
        'medianLocalizationSigmaNm', ...
        'experimentalJointPosteriorMeanDiffusionUm2PerS', ...
        'experimentalJointPosteriorLower95Um2PerS', ...
        'experimentalJointPosteriorUpper95Um2PerS', ...
        'experimentalJointDiffusionEffectiveSampleSize', ...
        'experimentalJointDiffusionSplitRhat', ...
        'experimentalPosteriorMeanEmittersInFocus', ...
        'experimentalMapTotalActiveEmitters', ...
        'experimentalTotalCountDecisionProbability', ...
        'experimentalTotalCountEntropyBits', ...
        'experimentalMedianFrameCountDecisionProbability', ...
        'experimentalAdjacentCountSeparationSigma', ...
        'experimentalCountDiagnosticsPassed', ...
        'experimentalJointPassedApplicabilityChecks', ...
        'experimentalJointValidatedForUse'});
    writetable(summary, fullfile(outputDir, 'diffusion_fit_summary.csv'));
    writetable(struct2table(diffusion.truthValidation, 'AsArray', true), ...
        fullfile(outputDir, 'diffusion_truth_validation.csv'));
    writetable(struct2table(densityDiagnostics, 'AsArray', true), ...
        fullfile(outputDir, 'density_diagnostics.csv'));
    if experimentalBnp.estimateAvailable && ...
            height(experimentalBnp.trace) > 0
        writetable(experimentalBnp.trace, fullfile(outputDir, ...
            'experimental_joint_sampler_trace.csv'));
    end
    if experimentalBnp.countEstimateAvailable && ...
            height(experimentalBnp.frameEmitterCountPosterior) > 0
        writetable(experimentalBnp.frameEmitterCountPosterior, ...
            fullfile(outputDir, ...
            'experimental_frame_emitter_count_posterior.csv'));
    end

    if opts.saveMovieStack
        save(fullfile(outputDir, 'membrane_diffusion_movie_stack.mat'), ...
            'frames', '-v7.3');
    end

    save(fullfile(outputDir, 'membrane_diffusion_tracking_result.mat'), ...
        'opts', 'detector', 'trajectories', 'photophysics', ...
        'localizationTable', 'trackTable', 'diffusion', ...
        'densityDiagnostics', 'experimentalBnp');
end
